import Foundation
import XCTest
@testable import ColorComposerCore

/// Replays the committed v1 corpus generated by `viamin/color_matching` issue
/// #111. The fixture is deliberately kept as upstream JSON rather than copied
/// into Swift so changes in solver semantics require an explicit corpus refresh.
final class WeightedSquaredErrorParityCorpusTests: XCTestCase {
    private let scorer = WeightedSquaredErrorScorer()

    func testCorpusMetadataPinsTheUpstreamAlgorithmContract() throws {
        let corpus = try loadCorpus()

        XCTAssertEqual(corpus.algorithmVersion, 1)
        XCTAssertEqual(corpus.selection, "earliest-index-wins")
        XCTAssertEqual(corpus.missingPolicy, "excluded-when-any-positive-weight-channel-missing")
        XCTAssertEqual(corpus.scenarios.count, 12)
    }

    func testEveryCandidateScoreMatchesTheParityCorpusExactly() throws {
        let corpus = try loadCorpus()

        for scenario in corpus.scenarios {
            let target = TargetResponseVector(responses(from: scenario.target.channels))
            let weights = channelWeights(from: scenario.weights)

            for expectedScore in scenario.expected.scores {
                let candidate = try XCTUnwrap(
                    scenario.palette.first(where: { $0.index == expectedScore.index }),
                    "Corpus scenario \(scenario.id) is missing candidate \(expectedScore.index)"
                )
                let actual = scorer.score(
                    candidate: paletteColor(from: candidate),
                    target: target,
                    weights: weights
                )
                assert(actual, matches: expectedScore.score, scenarioID: scenario.id, candidateIndex: candidate.index!)
            }
        }
    }

    func testSolverSelectionMatchesCorpusIncludingTieCases() throws {
        let corpus = try loadCorpus()

        for scenario in corpus.scenarios {
            let target = TargetResponseVector(responses(from: scenario.target.channels))
            let weights = channelWeights(from: scenario.weights)
            let palette = scenario.palette.sorted { $0.index! < $1.index! }.map(paletteColor)
            let scores = palette.map { scorer.score(candidate: $0, target: target, weights: weights) }
            let selected = earliestLowestScore(in: scores)

            XCTAssertEqual(selected, scenario.expected.selectedIndex, "Scenario \(scenario.id)")
            XCTAssertEqual(selected.map { palette[$0].hex }, scenario.expected.selectedHexColor, "Scenario \(scenario.id)")

            if let selected, let expectedError = scenario.expected.error {
                guard case .score(let actualError) = scores[selected] else {
                    return XCTFail("Selected candidate was excluded in scenario \(scenario.id)")
                }
                XCTAssertEqual(actualError, expectedError, "Scenario \(scenario.id)")
            } else {
                XCTAssertNil(scenario.expected.error, "Scenario \(scenario.id) expected a selected error")
            }

            let actualTiedIndices = tiedLowestIndices(in: scores)
            XCTAssertEqual(actualTiedIndices, scenario.expected.tiedIndices, "Scenario \(scenario.id)")
            XCTAssertEqual(actualTiedIndices.count > 1, scenario.expected.tieBroke ?? false, "Scenario \(scenario.id)")

            // The public solver must make the same selection whenever the corpus
            // target contains every positive-weight channel. A missing target is
            // represented by scorer exclusion in the corpus and cannot form a
            // source grid for `CompositionSolver`.
            if hasEveryActiveTargetChannel(scenario.target.channels, weights: weights) {
                let result = try CompositionSolver().solve(
                    palette: palette,
                    sourceGrids: sourceGrids(from: scenario.target.channels, weights: weights),
                    weights: weights
                )
                XCTAssertEqual(result.colorIndex(x: 0, y: 0), scenario.expected.selectedIndex, "Scenario \(scenario.id)")
                if let expectedError = scenario.expected.error {
                    XCTAssertEqual(result.error(x: 0, y: 0), expectedError, "Scenario \(scenario.id)")
                }
            }
        }
    }

    private func loadCorpus() throws -> ParityCorpus {
        let fixture = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .appendingPathComponent("Fixtures/weighted_squared_error_v1.json")
        let data = try Data(contentsOf: fixture)
        let decoder = JSONDecoder()
        decoder.keyDecodingStrategy = .convertFromSnakeCase
        return try decoder.decode(ParityCorpus.self, from: data)
    }

    private func paletteColor(from candidate: ParityCandidate) -> PaletteColor {
        PaletteColor(
            id: candidate.index!,
            hex: candidate.hexColor,
            rgb: RGBColor(hex: candidate.hexColor)!,
            responses: responses(from: candidate.channels).mapValues(IlluminationResponse.init(brightness:))
        )
    }

    private func responses(from channels: [String: Double]) -> [LightingCondition: Double] {
        channels.reduce(into: [:]) { result, entry in
            if let condition = LightingCondition(rawValue: entry.key) {
                result[condition] = entry.value
            }
        }
    }

    private func channelWeights(from weights: [String: Double]) -> ChannelWeights {
        ChannelWeights(
            white: weights["white", default: 0], red: weights["red", default: 0],
            green: weights["green", default: 0], blue: weights["blue", default: 0],
            lps: weights["lps", default: 0]
        )
    }

    private func sourceGrids(
        from channels: [String: Double], weights: ChannelWeights
    ) -> [LightingCondition: BrightnessGrid] {
        Dictionary(uniqueKeysWithValues: weights.activeConditions.map { condition in
            (condition, BrightnessGrid(width: 1, height: 1, fill: channels[condition.rawValue]!))
        })
    }

    private func hasEveryActiveTargetChannel(_ channels: [String: Double], weights: ChannelWeights) -> Bool {
        weights.activeConditions.allSatisfy { channels[$0.rawValue] != nil }
    }

    private func earliestLowestScore(in scores: [ScorerResult]) -> Int? {
        scores.enumerated().reduce(into: (index: Int?.none, score: Double.infinity)) { best, entry in
            guard case .score(let score) = entry.element, score < best.score else { return }
            best = (entry.offset, score)
        }.index
    }

    private func tiedLowestIndices(in scores: [ScorerResult]) -> [Int] {
        guard let best = earliestLowestScore(in: scores), case .score(let score) = scores[best] else { return [] }
        return scores.enumerated().compactMap { index, result in
            guard case .score(let candidateScore) = result, candidateScore == score else { return nil }
            return index
        }
    }

    private func assert(
        _ actual: ScorerResult,
        matches expected: ExpectedScore,
        scenarioID: String,
        candidateIndex: Int,
        file: StaticString = #filePath,
        line: UInt = #line
    ) {
        switch (actual, expected) {
        case (.excluded, .excluded):
            break
        case (.score(let actual), .score(let expected)):
            XCTAssertEqual(actual, expected, "Scenario \(scenarioID), candidate \(candidateIndex)", file: file, line: line)
        default:
            XCTFail("Scenario \(scenarioID), candidate \(candidateIndex): \(actual) did not match \(expected)", file: file, line: line)
        }
    }
}

private struct ParityCorpus: Decodable {
    let algorithmVersion: Int
    let missingPolicy: String
    let selection: String
    let scenarios: [ParityScenario]
}

private struct ParityScenario: Decodable {
    let id: String
    let palette: [ParityCandidate]
    let target: ParityCandidate
    let weights: [String: Double]
    let expected: ParityExpected
}

private struct ParityCandidate: Decodable {
    let channels: [String: Double]
    let hexColor: String
    let index: Int?
}

private struct ParityExpected: Decodable {
    let error: Double?
    let scores: [ParityScore]
    let selectedHexColor: String?
    let selectedIndex: Int?
    let tieBroke: Bool?
    let tiedIndices: [Int]
}

private struct ParityScore: Decodable {
    let index: Int
    let score: ExpectedScore
}

private enum ExpectedScore: Decodable, CustomStringConvertible {
    case excluded
    case score(Double)

    init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let score = try? container.decode(Double.self) {
            self = .score(score)
        } else if try container.decode(String.self) == "excluded" {
            self = .excluded
        } else {
            throw DecodingError.dataCorruptedError(in: container, debugDescription: "Expected score or excluded")
        }
    }

    var description: String {
        switch self {
        case .excluded: return "excluded"
        case .score(let value): return "score(\(value))"
        }
    }
}
